package com.restro.restaurantservice.web.controller;
import com.restro.restaurantservice.service.TableService; import com.restro.restaurantservice.web.dto.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/reservations") public class ReservationController { private final TableService service; public ReservationController(TableService service){this.service=service;} @GetMapping @PreAuthorize("hasAnyRole('OWNER','ADMIN','MANAGER','WAITER','CASHIER')") public List<ReservationResponse> list(){return service.reservations();} @PostMapping @PreAuthorize("hasAnyRole('OWNER','ADMIN','MANAGER','WAITER','CASHIER')") public ResponseEntity<ReservationResponse> create(@Valid @RequestBody ReservationRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.reserve(r));}}
